pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint128 _virtualBaseTokenReserves, uint128 _virtualNftReserves, uint56 _changeFee, uint16 _feeRate, bytes32 _merkleRoot) public {
        // keep domain wide: only constrain _feeRate to values that trigger the difference
        vm.assume(_feeRate > 5000);
        address _baseToken = address(0);
        address _nft = address(0);
        bool _useStolenNftOracle = false;
        bool _payRoyalties = false;

        vm.expectRevert();
        c.initialize(_baseToken, _nft, _virtualBaseTokenReserves, _virtualNftReserves, _changeFee, _feeRate, _merkleRoot, _useStolenNftOracle, _payRoyalties);

        // after the reverting call, feeRate should remain unset (0) per the original contract's behavior;
        // the bug stores the high feeRate before reverting, so observe the stored value
        uint16 storedFee = c.feeRate();
        assertTrue(storedFee <= 5000 || storedFee == 0);
    }
}

