pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this), address(this), address(this));
    }

    function testFuzz_property(uint16 feeRate1, uint16 feeRate2) public {
        // feeRate1 must be invalid (>5000) so the first initialize reverts on the bug.
        vm.assume(feeRate1 > 5000);
        // feeRate2 must be valid (<=5000) so the second initialize succeeds.
        vm.assume(feeRate2 <= 5000);
        // Make the first call revert.
        try c.initialize(
            address(0),
            address(0),
            0,
            0,
            0,
            feeRate1,
            bytes32(0),
            false,
            false
        ) {} catch {}
        // Successful call with a valid fee rate.
        c.initialize(
            address(0),
            address(0),
            0,
            0,
            0,
            feeRate2,
            bytes32(0),
            false,
            false
        );
        // After the successful call, the stored fee rate must equal the supplied valid fee rate.
        assertEq(c.feeRate(), feeRate2);
    }
}

