    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(bool fuzzUseStolenNftOracle) public {
        // drive the initialization with a fuzzed boolean
        c.initialize(
            address(0), /* _baseToken */
            address(1), /* _nft */
            0,         /* _virtualBaseTokenReserves */
            0,         /* _virtualNftReserves */
            0,         /* _changeFee */
            0,         /* _feeRate */
            bytes32(0),/* _merkleRoot */
            fuzzUseStolenNftOracle, /* _useStolenNftOracle */
            false      /* _payRoyalties */
        );

        // THE PROPERTY: after a successful initialize, the stored useStolenNftOracle
        // must equal the boolean that was passed as _useStolenNftOracle to the function.
        // (The bug writes the stored flag AFTER the event emission, so a listener
        // observing the event sees a stale value.)
        assertTrue(c.useStolenNftOracle() == fuzzUseStolenNftOracle);
    }
}

